// Fetch and insert reusable header HTML,then wire up hamburger toggle(function(){const headerPath='/includes/header.html';function insertHeader(html){const placeholder=document.getElementById('site-header');if(placeholder){placeholder.innerHTML=html;}else{const body=document.body;const temp=document.createElement('div');temp.innerHTML=html;body.insertBefore(temp.firstElementChild,body.firstChild);}const menuHamburguer=document.querySelector('.menu-hamburguer');const navLinks=document.querySelector('.nav-links');if(menuHamburguer && navLinks){menuHamburguer.addEventListener('click',()=>{navLinks.classList.toggle('active');});}}fetch(headerPath,{cache: 'no-store'}).then(r=>{if(!r.ok)throw new Error('Header fetch failed');return r.text();}).then(insertHeader).catch(err=> console.warn('Could not load header:',err));})();